script:
(function () {
  'use strict';

  var video = document.getElementById('cameraVideo');
  var previewWrap = document.getElementById('cameraPreviewWrap');
  var placeholder = document.getElementById('cameraPlaceholder');
  var canvas = document.getElementById('analysisCanvas');
  var deviceSelect = document.getElementById('deviceSelect');
  var btnStart = document.getElementById('btnStartCamera');
  var btnStop = document.getElementById('btnStopCamera');
  var diagnosticPanel = document.getElementById('diagnosticPanel');
  var sharpnessFill = document.getElementById('sharpnessFill');
  var sharpnessLabel = document.getElementById('sharpnessLabel');
  var statScore = document.getElementById('statScore');
  var statBest = document.getElementById('statBest');
  var statVerdict = document.getElementById('statVerdict');
  var statVariance = document.getElementById('statVariance');
  var statNeeded = document.getElementById('statNeeded');
  var statNoise = document.getElementById('statNoise');
  var statLighting = document.getElementById('statLighting');
  var statFps = document.getElementById('statFps');
  var statMegapixels = document.getElementById('statMegapixels');
  var statAspect = document.getElementById('statAspect');
  var statWebcam = document.getElementById('statWebcam');
  var chartCanvas = document.getElementById('chartCanvas');
  var chartPreviewImg = document.getElementById('chartPreviewImg');
  var btnDownloadChart = document.getElementById('btnDownloadChart');

  var currentStream = null;
  var starting = false;
  var analysisTimer = null;
  var peakVariance = 0;
  var prevGray = null;
  var noiseHistory = [];
  var reportedFps = 0;
  var fpsLoopId = null;
  var fpsCount = 0;
  var fpsStart = 0;
  var measuredFps = 0;

  function escapeHtml(s) {
    var d = document.createElement('div');
    d.textContent = String(s);
    return d.innerHTML;
  }

  function setDiagnostic(items) {
    diagnosticPanel.innerHTML = items.map(function (it) {
      var sevClass = it.sev ? ' sev-' + it.sev : '';
      return '<div class="diagnostic-item' + sevClass + '"><span class="diag-icon" aria-hidden="true">' +
        '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/></svg>' +
        '</span><span>' + it.html + '</span></div>';
    }).join('');
  }

  // Same stopStream()/describeError()/populateDeviceSelect() pattern as
  // webcam-test-online's own script (see this project's CLAUDE.md -- every
  // camera tool copies this teardown block rather than importing a shared file).
  function stopStream() {
    if (analysisTimer) { clearInterval(analysisTimer); analysisTimer = null; }
    if (currentStream) {
      currentStream.getTracks().forEach(function (t) { t.stop(); });
      currentStream = null;
    }
    video.srcObject = null;
    previewWrap.classList.remove('is-active');
    placeholder.style.display = 'flex';
    btnStop.disabled = true;
    stopFpsMeter();
    prevGray = null;
    noiseHistory = [];
    sharpnessFill.style.width = '0%';
    sharpnessLabel.textContent = '—';
    [statScore, statVerdict, statVariance, statNoise, statLighting, statFps].forEach(function (el) { el.textContent = '—'; });
  }

  // Real frame rate: frames the camera actually delivers, counted with
  // requestVideoFrameCallback (falls back to the track's reported rate).
  function fpsLoop() {
    if (!currentStream) return;
    fpsCount++;
    var t = performance.now();
    if (!fpsStart) fpsStart = t;
    if (t - fpsStart >= 1000) {
      measuredFps = fpsCount * 1000 / (t - fpsStart);
      fpsCount = 0;
      fpsStart = t;
    }
    fpsLoopId = video.requestVideoFrameCallback(fpsLoop);
  }

  function startFpsMeter() {
    fpsCount = 0; fpsStart = 0; measuredFps = 0;
    if (video.requestVideoFrameCallback) fpsLoopId = video.requestVideoFrameCallback(fpsLoop);
  }

  function stopFpsMeter() {
    if (fpsLoopId !== null && video.cancelVideoFrameCallback) video.cancelVideoFrameCallback(fpsLoopId);
    fpsLoopId = null;
    measuredFps = 0;
  }

  function gcd(a, b) { return b ? gcd(b, a % b) : a; }

  function showStreamInfo(track, settings) {
    var w = settings.width || video.videoWidth, h = settings.height || video.videoHeight;
    statWebcam.textContent = track.label || 'Not selected';
    statMegapixels.textContent = w && h ? (w * h / 1000000).toFixed(2) + ' MP' : '—';
    statAspect.textContent = w && h ? (w / gcd(w, h)) + ':' + (h / gcd(w, h)) : '—';
    reportedFps = settings.frameRate || 0;
  }

  function noiseBand(n) {
    if (n < 2) return 'Clean';
    if (n < 4) return 'Low noise';
    if (n < 8) return 'Moderate (indoor lighting)';
    if (n < 15) return 'Noisy: add light';
    return 'Very grainy: add light';
  }

  function lightingBand(b) {
    if (b < 50) return 'Too dark';
    if (b < 80) return 'Dim';
    if (b <= 180) return 'Good lighting';
    if (b < 220) return 'Bright';
    return 'Overexposed';
  }

  function describeError(err) {
    switch (err && err.name) {
      case 'NotAllowedError':
      case 'PermissionDeniedError':
        return { sev: 'error', html: '<strong>Camera access was blocked.</strong> Allow access from your browser’s address-bar icon or site settings, then try again.' };
      case 'NotFoundError':
      case 'DevicesNotFoundError':
        return { sev: 'error', html: '<strong>No camera was detected.</strong> Connect a webcam and reload this page.' };
      case 'NotReadableError':
      case 'TrackStartError':
        return { sev: 'error', html: '<strong>Your camera is already in use</strong> by another app or browser tab.' };
      case 'OverconstrainedError':
        return { sev: 'error', html: '<strong>This camera doesn’t support the requested settings.</strong> Try another camera from the list.' };
      case 'SecurityError':
        return { sev: 'error', html: '<strong>Camera access requires HTTPS.</strong>' };
      default:
        return { sev: 'error', html: '<strong>Something went wrong starting the camera.</strong> ' + escapeHtml((err && err.message) || 'Unknown error') + '.' };
    }
  }

  function populateDeviceSelect(devices, currentDeviceId) {
    var cams = devices.filter(function (d) { return d.kind === 'videoinput'; });
    deviceSelect.innerHTML = '';
    cams.forEach(function (d, i) {
      var opt = document.createElement('option');
      opt.value = d.deviceId;
      opt.textContent = d.label || ('Camera ' + (i + 1));
      if (d.deviceId === currentDeviceId) opt.selected = true;
      deviceSelect.appendChild(opt);
    });
    deviceSelect.disabled = cams.length === 0;
  }

  function classify(score) {
    if (score > 100) return 'Check noise';
    if (score >= 85) return 'Sharp';
    if (score >= 60) return 'Slightly soft';
    if (score >= 35) return 'Soft';
    return 'Blurry';
  }

  // Downsample heavily before the convolution or the loop won't keep up --
  // 140px on the long edge is plenty for a variance-of-Laplacian estimate.
  function measureSharpness() {
    if (!currentStream || !video.videoWidth) return;
    var w = video.videoWidth, h = video.videoHeight;
    var scale = Math.min(1, 140 / Math.max(w, h));
    var sw = Math.max(8, Math.round(w * scale));
    var sh = Math.max(8, Math.round(h * scale));
    canvas.width = sw;
    canvas.height = sh;
    var ctx = canvas.getContext('2d');
    ctx.drawImage(video, 0, 0, sw, sh);

    var data;
    try {
      data = ctx.getImageData(0, 0, sw, sh).data;
    } catch (e) {
      return;
    }

    var gray = new Float32Array(sw * sh);
    for (var i = 0, p = 0; i < data.length; i += 4, p++) {
      gray[p] = data[i] * 0.299 + data[i + 1] * 0.587 + data[i + 2] * 0.114;
    }

    var lapSum = 0, lapSumSq = 0, count = 0;
    for (var y = 1; y < sh - 1; y++) {
      for (var x = 1; x < sw - 1; x++) {
        var idx = y * sw + x;
        var lap = 4 * gray[idx] - gray[idx - 1] - gray[idx + 1] - gray[idx - sw] - gray[idx + sw];
        lapSum += lap;
        lapSumSq += lap * lap;
        count++;
      }
    }
    if (!count) return;
    var mean = lapSum / count;
    var variance = Math.max(0, (lapSumSq / count) - (mean * mean));

    // Focus score = 100 x sqrt(variance / session peak variance): the square
    // root turns variance back into an edge-strength scale, so 50 means
    // edges about half as strong as in the sharpest frame seen this session.
    if (variance > peakVariance) peakVariance = variance;
    var score = peakVariance > 0 ? 100 * Math.sqrt(variance / peakVariance) : 0;
    var verdict = classify(score);

    // Noise: spread of the difference between consecutive samples / sqrt(2)
    // (the lowest of the last few, so normal movement doesn't count as grain).
    var brightnessSum = 0;
    for (var b = 0; b < gray.length; b++) brightnessSum += gray[b];
    var brightness = brightnessSum / gray.length;
    if (prevGray && prevGray.length === gray.length) {
      var dS = 0, dS2 = 0;
      for (var k = 0; k < gray.length; k++) { var df = gray[k] - prevGray[k]; dS += df; dS2 += df * df; }
      var dm = dS / gray.length;
      noiseHistory.push(Math.sqrt(Math.max(0, dS2 / gray.length - dm * dm)) / Math.SQRT2);
      if (noiseHistory.length > 8) noiseHistory.shift();
    }
    prevGray = gray;

    sharpnessFill.style.width = Math.min(100, score) + '%';
    sharpnessLabel.textContent = score.toFixed(1) + ' — ' + verdict;
    statScore.textContent = score.toFixed(1);
    statVerdict.textContent = verdict;
    statVariance.textContent = variance.toFixed(1);
    statBest.textContent = peakVariance.toFixed(1);
    statNeeded.textContent = (0.85 * 0.85 * peakVariance).toFixed(1);
    if (noiseHistory.length) {
      var noise = Math.min.apply(null, noiseHistory);
      statNoise.textContent = noise.toFixed(1) + ' — ' + noiseBand(noise);
    }
    statLighting.textContent = Math.round(brightness) + '/255 — ' + lightingBand(brightness);
    var fps = measuredFps || reportedFps;
    statFps.textContent = fps ? fps.toFixed(1) + (fps < 20 ? ' (low)' : '') : '—';
  }

  function startStream(deviceId) {
    if (starting) return;
    starting = true;
    stopStream();
    peakVariance = 0;
    statBest.textContent = '—';
    statNeeded.textContent = '—';
    setDiagnostic([{ sev: '', html: 'Requesting camera access…' }]);
    btnStart.disabled = true;

    navigator.mediaDevices.getUserMedia({ video: deviceId ? { deviceId: { exact: deviceId } } : true, audio: false })
      .then(function (stream) {
        currentStream = stream;
        video.srcObject = stream;
        placeholder.style.display = 'none';
        previewWrap.classList.add('is-active');
        return video.play().catch(function () {}).then(function () { return stream; });
      })
      .then(function (stream) {
        var track = stream.getVideoTracks()[0];
        var settings = track.getSettings ? track.getSettings() : {};
        btnStop.disabled = false;
        showStreamInfo(track, settings);
        startFpsMeter();
        setDiagnostic([{ sev: 'ok', html: '<strong>Camera is live.</strong> Hold a printed page still in front of the camera to set the peak, then adjust focus or move back to your seat while watching the meter.' }]);
        analysisTimer = setInterval(measureSharpness, 250);
        return navigator.mediaDevices.enumerateDevices().then(function (devices) {
          populateDeviceSelect(devices, settings.deviceId);
        });
      })
      .catch(function (err) { setDiagnostic([describeError(err)]); stopStream(); })
      .finally(function () { starting = false; btnStart.disabled = false; });
  }

  // Draws a Siemens-star focus chart (alternating black/white wedges radiating
  // from the centre) plus concentric rings -- the industry-standard pattern
  // for manual focus verification, since blur shows up first as the fine
  // spokes near the centre merging into grey.
  function drawFocusChart() {
    var size = 1200;
    chartCanvas.width = size;
    chartCanvas.height = size;
    var ctx = chartCanvas.getContext('2d');
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, size, size);

    var cx = size / 2, cy = size / 2;
    var outerR = size * 0.46;
    var wedges = 36;
    for (var i = 0; i < wedges; i++) {
      ctx.beginPath();
      ctx.moveTo(cx, cy);
      var a0 = (i / wedges) * Math.PI * 2;
      var a1 = ((i + 1) / wedges) * Math.PI * 2;
      ctx.arc(cx, cy, outerR, a0, a1);
      ctx.closePath();
      ctx.fillStyle = (i % 2 === 0) ? '#000000' : '#ffffff';
      ctx.fill();
    }

    ctx.strokeStyle = '#000000';
    ctx.lineWidth = 3;
    [0.15, 0.28, 0.46].forEach(function (r) {
      ctx.beginPath();
      ctx.arc(cx, cy, size * r, 0, Math.PI * 2);
      ctx.stroke();
    });

    ctx.fillStyle = '#000000';
    ctx.font = 'bold 28px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('WebcamTest Focus Chart', cx, size * 0.96);
    ctx.font = '18px sans-serif';
    ctx.fillText('Fine spokes near the centre should stay distinct when in focus', cx, size * 0.06);

    chartPreviewImg.src = chartCanvas.toDataURL('image/png');
  }

  btnStart.addEventListener('click', function () { startStream(deviceSelect.value); });
  btnStop.addEventListener('click', function () {
    stopStream();
    setDiagnostic([{ sev: '', html: 'Camera stopped.' }]);
  });
  deviceSelect.addEventListener('change', function () { if (currentStream) startStream(deviceSelect.value); });

  btnDownloadChart.addEventListener('click', function () {
    var url = chartCanvas.toDataURL('image/png');
    var a = document.createElement('a');
    a.href = url;
    a.download = 'webcamtest-focus-chart.png';
    document.body.appendChild(a);
    a.click();
    a.remove();
  });

  window.addEventListener('pagehide', stopStream);
  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'hidden') stopStream();
  });

  drawFocusChart();

  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
    setDiagnostic([{ sev: 'error', html: '<strong>Your browser doesn’t support camera access.</strong>' }]);
    btnStart.disabled = true;
  }
})();
